const void *GnGeoFindDriver(const char *name, Uint32 *size){if(!name)return NULL; for(size_t i=0;i<sizeof(Drivers)/sizeof(Drivers[0]);i++)if(!strcasecmp(Drivers[i].name,name)){if(size)*size=Drivers[i].size;return Drivers[i].data;}if(size)*size=0;return NULL;}
